#!/usr/bin/env python3
"""
Round 114b (culprits), 29 September 2026. Needs round 113b.

The holidays row cut to those who corporatized holidays; sports facilities, sports betting and rigged games; the pet food industry, animal breeding places and zoos and aquariums worldwide.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 114b (29 September)\n\nNeeds round 113b. Tiles patch round114b_tiles.py beside it. No app.js?v= bump.\n\n- holiday_culprits: corporatizers only (owner: the made-to-replace holidays\n  out; "sales events" entries looked like companies that sold a lot around\n  holidays). Kept 12 whose own write-ups say they made the holiday a company\n  custom or invented one (Coca-Cola, Macy\'s, Montgomery Ward, Alibaba,\n  Amazon, NRF, Father\'s Day Council, Ishimuramanseido, Cleveland\n  confectioners, NCA, Lotte, KFC Japan); out: the six governments/bodies,\n  JD.com, Hallmark and American Greetings (card counts only). Tiles\n  holidays/culprits.geojson rewritten. Research for more corporatizers was not\n  possible (web lookups unanswered); add from sources next time.\n- New rows (Suppression > Sports): sports_facilities (tiles\n  sports_facilities.py: Overture latest release via DuckDB on the open bucket,\n  places with sport categories + base land_use sport classes by name, logged\n  in sports/build.json; squares z0-7, each place z8 in strips via\n  lib/pointtiles.py; drawn by addMvtCopy, colour by group), sports_betting and\n  sports_fixing (Wikidata via lib/wdtools.py: kinds resolved by exact English\n  name with subclasses, numbers logged; placed by own coords, HQ, location,\n  country; fixing has a year bar).\n- Animal rows made worldwide: animal_breeding_osm (OSM animal_breeding=*),\n  zoos_aquariums_osm (tourism=zoo|aquarium, grouped by zoo=* or aquarium) and\n  a probe of the Zoos Google map for aquarium names (probe/zoos_kml.json),\n  from tiles animal_places_osm.py; pet_food_world (Wikidata industry/product\n  pet food, pet food brand/company kinds, owners named).\n- addMvtCopy generalised (_count for squares; unit in boxes); a copy-only row\n  says "not built yet" until its build.json exists; waiting texts on the\n  Wikidata/OSM rows.\n- The medical-industry layer waits for the owner\'s Suppression-page HTML\n  (not attached yet).\n\n'
HEAD = '## Round 114b (29 September)'


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round114b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 113b" not in text:
        sys.exit("round114b: round 113b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round114b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round114b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round114b: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round ")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
